        return {
          allowed: false,
          nextSendAt: new Date(store.nowMs + 8 * 3600_000),
          zones: ['America/New_York'],
          endHour: 21,
        };
      }
      if ((store as { forceQuiet?: boolean }).forceQuiet === false) {
        return {
          allowed: true,
          zones: ['America/New_York'],
          endHour: 21,
        };
      }
      return actual.deferUntilQuietHoursOpen(now, opts as never);
