  it('duplicate sid: confirm / needs_review / claim_deferred / in_flight', async () => {
    const cases: Array<[string, string]> = [
      ['delivered', 'sent'],
      ['failed', 'needs_review'],
      ['sending', 'blocked'],
    ];
    for (const [status, kind] of cases) {
      const sid = 'mlf:recovery:Ldup';
      const db = makeDb({
        leads: { opted_out: false },
        insertError: { code: '23505', message: 'dup' },
        smsBySid: new Map([[sid, { status }]]),
      });
      const o = await sendMessageWithDeps(baseDeps({ dbImpl: db }), {
        kind: 'recovery',
        leadId: 'Ldup',
        businessId: 'B',
        to: '+12135550100',
        body: 'hi',
        idempotencyKey: sid,
      });
      expect(o.kind, status).toBe(kind);
    }

    const sid = 'mlf:recovery:Ldef';
    const send = vi.fn(async () => ({
      id: 'm',
      status: 'queued',
      keyEchoed: true,
    }));
    const db = makeDb({
      leads: { opted_out: false },
      insertError: { code: '23505', message: 'dup' },
      smsBySid: new Map([[sid, { status: 'deferred' }]]),
    });
    const o = await sendMessageWithDeps(
      baseDeps({
        dbImpl: db,
        adapter: () => ({ name: 'm', sendMessage: send }) as never,
      }),
      {
        kind: 'recovery',
        leadId: 'Ldef',
        businessId: 'B',
        to: '+12135550100',
        body: 'hi',
        idempotencyKey: sid,
      }
    );
    expect(o.kind).toBe('sent');
    expect(send).toHaveBeenCalled();
  });

  it('relay ok / conflict / maintenance / failed / throw', async () => {
    const mk = async (result: unknown | Error) => {
      const db = makeDb({ leads: { opted_out: false } });
      const send =
        result instanceof Error
          ? vi.fn(async () => {
              throw result;
            })
          : vi.fn(async () => result);
      return sendMessageWithDeps(
        baseDeps({
          dbImpl: db,
          adapter: () => ({ name: 'm', sendMessage: send }) as never,
        }),
        {
          kind: 'recovery',
          leadId: 'L',
          businessId: 'B',
          to: '+12135550100',
          body: 'hi',
        }
      );
    };
    expect((await mk({ id: 'm', status: 'queued', keyEchoed: true })).kind).toBe(
      'sent'
    );
    expect((await mk({ id: 'm', conflict: true })).kind).toBe('needs_review');
    expect(
      (await mk({ id: 'm', ambiguous: true, status: 'maintenance' })).kind
    ).toBe('ambiguous');
    expect((await mk({ id: 'm', ambiguous: true })).kind).toBe('ambiguous');
    expect((await mk({ id: 'm', status: 'failed' })).kind).toBe('needs_review');
    expect((await mk(new Error('boom'))).kind).toBe('ambiguous');
  });

  it('manual/escalation skips customer gates and still sends', async () => {
    const send = vi.fn(async () => ({
      id: 'm',
      status: 'queued',
      keyEchoed: true,
    }));
    const o = await sendMessageWithDeps(
      baseDeps({
        dbImpl: makeDb({}),
        adapter: () => ({ name: 'm', sendMessage: send }) as never,
        isPhoneSuppressed: async () => true,
      }),
      {
        kind: 'manual',
        leadId: 'L',
        businessId: 'B',
        to: '+12135550100',
        body: 'hi',
      }
    );
    expect(o.kind).toBe('sent');
  });

  it('select uses opted_out, timezone, sms_outbound_sid', async () => {
    const db = makeDb({ leads: { opted_out: false, timezone: 'America/Chicago' } });
    const send = vi.fn(async () => ({
      id: 'm',
      status: 'queued',
      keyEchoed: true,
    }));
    await sendMessageWithDeps(
      baseDeps({
        dbImpl: db,
        adapter: () => ({ name: 'm', sendMessage: send }) as never,
      }),
      {
        kind: 'recovery',
        leadId: 'L',
        businessId: 'B',
        to: '+12135550100',
        body: 'hi',
      }
    );
    const sel = db.calls.find(
      (c) => c.table === 'leads' && c.op === 'select'
    );
    expect(sel?.args[0]).toBe('opted_out, timezone, sms_outbound_sid');
    const insert = db.calls.find(
      (c) => c.table === 'sms_messages' && c.op === 'insert'
    );
    expect(insert?.args[0]).toMatchObject({
      lead_id: 'L',
      direction: 'outbound',
      body: 'hi',
      status: 'sending',
      key_supported_at_send: false,
    });
    const upd = db.calls.find(
      (c) =>
        c.table === 'sms_messages' &&
        c.op === 'update' &&
        (c.args[0] as { status?: string })?.status === 'queued'
    );
    expect(upd?.args[0]).toMatchObject({
      status: 'queued',
      key_supported_at_send: true,
    });
  });
});

