describe('sendRecoverySMSWithDeps', () => {
  it('persists deferred on quiet_hours_deferred', async () => {
    const db = makeDb({ existing: null });
    const persistSpy = vi.fn();
    const d = deps({
      dbImpl: db,
      sendMessage: async () => ({
        kind: 'blocked',
        reason: 'quiet_hours_deferred',
        nextSendAt: '2026-06-16T12:00:00.000Z',
